```java
import java.util.Scanner;

public class CarbonCalculator {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter miles driven: ");
        double miles = sc.nextDouble();
        System.out.print("Enter electricity consumed (kWh): ");
        double kWh = sc.nextDouble();
        System.out.print("Enter waste generated (kg): ");
        double waste = sc.nextDouble();
        System.out.print("Recycled? (1/0): ");
        int recycled = sc.nextInt();
        System.out.print("Public transport? (1/0): ");
        int pubTrans = sc.nextInt();

        double vehicleEmission = miles * 0.40;
        double electricityEmission = kWh * 0.85;
        double wasteEmission = waste * 1.20;
        double totalFootprint = vehicleEmission + electricityEmission + wasteEmission;

        boolean under20 = totalFootprint < 20;
        boolean ecoFriendly = under20 && (recycled == 1) && (pubTrans == 1);

        System.out.println("Vehicle Emission: " + vehicleEmission);
        System.out.println("Electricity Emission: " + electricityEmission);
        System.out.println("Waste Emission: " + wasteEmission);
        System.out.println("Total Footprint: " + totalFootprint);
        System.out.println("Under 20 achieved: " + under20);
        System.out.println("Eco-Friendly: " + ecoFriendly);
    }
}
```

