public double calculateAverageMileage(Truck[] trucks) {
    double totalMileage = 0;
    for (int i = 0; i < trucks.length; i++) {
        totalMileage += trucks[i].getDistance() / trucks[i].getFuel();
    }
    return totalMileage / trucks.length;
}
