public class MissionScoring {
    public static void main(String[] args) {
        int currentScore = 300;
        int missionNumber = 2;
        int coins = 55;
        int missionPoints = 0;

        switch (missionNumber) {
            case 1: missionPoints = 50; break;
            case 2: missionPoints = 100; break;
            case 3: missionPoints = 150; break;
            case 4: missionPoints = 250; break;
            default: missionPoints = 0; break;
        }

        currentScore += missionPoints;
        int bonus = (currentScore >= 500) ? 100 : 0;
        int finalScore = currentScore + bonus;

        String level;
        if (currentScore < 200) {
            level = "Beginner";
        } else if (currentScore < 400) {
            level = "Intermediate";
        } else if (currentScore < 700) {
            level = "Advanced";
        } else {
            level = "Master";
        }

        if (coins >= 50) {
            System.out.println("Extra Life Awarded!");
        } else {
            System.out.println("Keep Collecting Coins!");
        }

        System.out.println("Updated Score: " + currentScore);
        System.out.println("Bonus: " + bonus);
        System.out.println("Final Score: " + finalScore);
        System.out.println("Level: " + level);
    }
}
```

