public static double[] calculateFinalFees(Subscriber[] subs, double festivalDiscount) {
    int totalMovies = 0;
    for(Subscriber s : subs) {
        totalMovies += s.moviesWatched;
    }
    double addDisc = (totalMovies >= 20) ? 3.0 : (totalMovies >= 10 ? 2.0 : 0.0);
    double[] fees = new double[subs.length];
    for(int i = 0; i < subs.length; i++) {
        double baseFee = subs[i].plan.equals("Basic") ? 299 : (subs[i].plan.equals("Standard") ? 499 : 799);
        fees[i] = baseFee * (1 - (festivalDiscount + addDisc) / 100.0);
    }
    return fees;
}
```
