```java
public class Solution {
    static double festivalDiscount = 0.0;
    public static void setDiscountPercentage(double discount) {
        festivalDiscount = discount;
    }
    public static void main(String[] args) {
        int n = 3;
        Subscriber[] subs = new Subscriber[n];
        subs[0] = new Subscriber(1, "Basic", 5);
        subs[1] = new Subscriber(2, "Standard", 12);
        subs[2] = new Subscriber(3, "Premium", 25);

        int totalMovies = 0;
        for(int i=0; i<n; i++) totalMovies += subs[i].moviesWatched;

        double addDiscount = 0;
        if(totalMovies >= 20) addDiscount = 3;
        else if(totalMovies >= 10) addDiscount = 2;

        int basic=0, std=0, prem=0;
        double sumFees = 0;
        double[] fees = new double[n];

        for(int i=0; i<n; i++) {
            if(subs[i].plan.equals("Basic")) basic++;
            else if(subs[i].plan.equals("Standard")) std++;
            else if(subs[i].plan.equals("Premium")) prem++;

            double monthly = subs[i].plan.equals("Basic") ? 299 : (subs[i].plan.equals("Standard") ? 499 : 799);
            fees[i] = monthly * (1 - (festivalDiscount + addDiscount)/100.0);
            sumFees += fees[i];
        }

        double avg = sumFees / n;
        double maxFee = -1;
        int maxId = -1;

        for(int i=0; i<n; i++) {
            if(fees[i] > maxFee) {
                maxFee = fees[i];
                maxId = subs[i].id;
            }
        }

        System.out.println("Highest Fee ID: " + maxId);
        System.out.println("Basic: " + basic + ", Standard: " + std + ", Premium: " + prem);
    }
}
```

