```java
import java.util.Scanner;

class Subscriber {
    String id;
    String plan;
    int moviesWatched;
    double finalFee;
}

public class StreamingAssignment {
    public static double festivalDiscount = 0;
    public static void setDiscountPercentage(double discount) {
        festivalDiscount = discount;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        double disc = sc.nextDouble();
        setDiscountPercentage(disc);

        Subscriber[] subs = new Subscriber[n];
        int totalMovies = 0;
        int basic = 0, standard = 0, premium = 0;

        for(int i = 0; i < n; i++) {
            subs[i] = new Subscriber();
            subs[i].id = sc.next();
            subs[i].plan = sc.next();
            subs[i].moviesWatched = sc.nextInt();
            totalMovies += subs[i].moviesWatched;

            if(subs[i].plan.equalsIgnoreCase("Basic")) basic++;
            else if(subs[i].plan.equalsIgnoreCase("Standard")) standard++;
            else if(subs[i].plan.equalsIgnoreCase("Premium")) premium++;
        }

        double addDisc = 0;
        if(totalMovies >= 20) addDisc = 3;
        else if(totalMovies >= 10) addDisc = 2;

        double sumFees = 0;
        double maxFee = -1;
        String maxId = "";
        int addDiscCount = 0;

        for(int i = 0; i < n; i++) {
            double baseFee = subs[i].plan.equalsIgnoreCase("Basic") ? 299 : (subs[i].plan.equalsIgnoreCase("Standard") ? 499 : 799);
            subs[i].finalFee = baseFee * (1 - (festivalDiscount + addDisc) / 100.0);
            sumFees += subs[i].finalFee;

            if(subs[i].finalFee > maxFee) {
                maxFee = subs[i].finalFee;
                maxId = subs[i].id;
            }
            if(addDisc > 0) addDiscCount++;
        }

        double avgFee = sumFees / n;
        int aboveAvgCount = 0;
        for(int i = 0; i < n; i++) {
            if(subs[i].finalFee >= avgFee) aboveAvgCount++;
        }

        System.out.println("Max Fee ID: " + maxId);
        System.out.println("Counts: Basic=" + basic + ", Standard=" + standard + ", Premium=" + premium);
        System.out.println("Additional discount recipients: " + addDiscCount);
        System.out.println("Above or equal to avg count: " + aboveAvgCount);
    }
}
```

