        double kWh = 100.0;
        double waste = 10.0;
        int recycled = 1;
        int publicTransport = 1;

        double vehicleEmission = miles * 0.40;
        double electricityEmission = kWh * 0.85;
        double wasteEmission = waste * 1.20;
        double totalFootprint = vehicleEmission + electricityEmission + wasteEmission;

        boolean lessThan20 = totalFootprint < 20;
        boolean ecoFriendly = lessThan20 && (recycled == 1) && (publicTransport == 1);

        System.out.println("Vehicle Emission: " + vehicleEmission);
        System.out.println("Electricity Emission: " + electricityEmission);
        System.out.println("Waste Emission: " + wasteEmission);
        System.out.println("Total Footprint: " + totalFootprint);
        System.out.println("Less than 20 achieved: " + lessThan20);
        System.out.println("Eco-Friendly: " + ecoFriendly);
    }
}
```

