Here is the complete source code for the Passenger class and the main method to fulfill all requirements:

```java
import java.util.Scanner;

class Passenger {
    private String passengerId;
    private String airlineName;
    private double baggageWeight;
    private static double freeAllowance;

    static {
        freeAllowance = 20;
    }

    public Passenger(String id, String airline, double weight) {
        this.passengerId = id;
        this.airlineName = airline;
        this.baggageWeight = weight;
    }

    public double calculateExcessCharge() {
        if (baggageWeight > freeAllowance) {
            return (baggageWeight - freeAllowance) * 500;
        }
        return 0;
    }

    public static void setFreeAllowance(double allowance) {
        freeAllowance = allowance;
    }

    public String getPassengerId() {
        return passengerId;
    }
    public String getAirlineName() { return airlineName; }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Passenger p1 = new Passenger(sc.next(), sc.next(), sc.nextDouble());
        Passenger p2 = new Passenger(sc.next(), sc.next(), sc.nextDouble());

        System.out.println(p1.getPassengerId() + " " + p1.getAirlineName() + " " + p1.calculateExcessCharge());
        System.out.println(p2.getPassengerId() + " " + p2.getAirlineName() + " " + p2.calculateExcessCharge());

        String highest = (p1.calculateExcessCharge() > p2.calculateExcessCharge()) ? p1.getPassengerId() : p2.getPassengerId();
        System.out.println("Highest: " + highest);

        Passenger.setFreeAllowance(30);
        System.out.println("Sum: " + (p1.calculateExcessCharge() + p2.calculateExcessCharge()));
    }
}
```

