public static void countCategories(Truck[] trucks) {
    int excellent = 0, good = 0, average = 0, poor = 0;
    for (Truck t : trucks) {
        double m = t.getMileage();
        if (m >= 18) excellent++;
        else if (m >= 15) good++;
        else if (m >= 10) average++;
        else poor++;
    }
    System.out.println("Excellent: " + excellent);
    System.out.println("Good: " + good);
    System.out.println("Average: " + average);
    System.out.println("Poor: " + poor);
}
