import java.util.Scanner;

public class CarbonFootprint {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Miles driven: ");
        double miles = scanner.nextDouble();
        System.out.print("Electricity kWh: ");
        double kwh = scanner.nextDouble();
        System.out.print("Waste kg: ");
        double waste = scanner.nextDouble();
        System.out.print("Recycled (1/0): ");
        int recycled = scanner.nextInt();
        System.out.print("Public transport (1/0): ");
        int transport = scanner.nextInt();

        double vehicleEmission = miles * 0.40;
        double electricityEmission = kwh * 0.85;
        double wasteEmission = waste * 1.20;
        double totalFootprint = vehicleEmission + electricityEmission + wasteEmission;

        boolean under20 = totalFootprint < 20;
        boolean ecoFriendly = under20 && (recycled == 1) && (transport == 1);

        System.out.println("Vehicle emissions: " + vehicleEmission);
        System.out.println("Electricity emissions: " + electricityEmission);
        System.out.println("Waste emissions: " + wasteEmission);
        System.out.println("Total footprint: " + totalFootprint);
        System.out.println("Under 20 achieved: " + under20);
        System.out.println("Eco-friendly: " + ecoFriendly);
    }
}

