public static void main(String[] args) {
    Truck[] fleet = {
        new Truck("T1", "Alice", 500, 25),
        new Truck("T2", "Bob", 300, 25),
        new Truck("T3", "Charlie", 400, 30)
    };

    Truck best = fleet[0];
    double totalMileage = 0;
    int excellent = 0, good = 0, average = 0, poor = 0;

    for (Truck t : fleet) {
        double m = t.calculateMileage();
        totalMileage += m;

        if (m > best.calculateMileage()) best = t;

        String cat = t.getCategory();
        if (cat.equals("Excellent")) excellent++;
        else if (cat.equals("Good")) good++;
        else if (cat.equals("Average")) average++;
        else poor++;
    }

