public class Truck {
    private String truckId;
    private String driverName;
    private double distanceTravelled;
    private double fuelConsumed;

    public Truck(String truckId, String driverName, double distanceTravelled, double fuelConsumed) {
        this.truckId = truckId;
        this.driverName = driverName;
        this.distanceTravelled = distanceTravelled;
        this.fuelConsumed = fuelConsumed;
    }

    public double getMileage() {
        return distanceTravelled / fuelConsumed;
    }

    public String getCategory() {
        double m = getMileage();
        if (m >= 18) return "Excellent";
        if (m >= 15) return "Good";
        if (m >= 10) return "Average";
        return "Poor";
    }
    // Getters and main array logic omitted for brevity...
}
```

