public static String getHighestFeeSubscriberID(Subscriber[] subs, double festivalDiscount, double additionalDiscount) {
    if (subs == null || subs.length == 0) return null;
    String maxId = subs[0].getId();
    double maxFee = calculateFinalFee(subs[0], festivalDiscount, additionalDiscount);

    for (int i = 1; i < subs.length; i++) {
        double fee = calculateFinalFee(subs[i], festivalDiscount, additionalDiscount);
        if (fee > maxFee) {
            maxFee = fee;
            maxId = subs[i].getId();
        }
    }
    return maxId;
}
