```java
import java.util.Scanner;

public class CarbonFootprint {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double miles = scanner.nextDouble();
        double kWh = scanner.nextDouble();
        double waste = scanner.nextDouble();
        int recycled = scanner.nextInt();
        int transport = scanner.nextInt();

        double vehicleEmission = miles * 0.40;
        double elecEmission = kWh * 0.85;
        double wasteEmission = waste * 1.20;
        double total = vehicleEmission + elecEmission + wasteEmission;

        boolean under20 = total < 20;
        boolean ecoFriendly = under20 && (recycled == 1) && (transport == 1);

        System.out.println(vehicleEmission);
        System.out.println(elecEmission);
        System.out.println(wasteEmission);
        System.out.println(total);
        System.out.println(under20);
        System.out.println(ecoFriendly);
    }
}
```

